def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid 1 column separates the pattern from its mask.
    sep = next(c for c in range(w) if all(grid[r][c] == 1 for r in range(h)))
    pattern = [row[:sep] for row in grid]
    mask = [row[sep + 1:sep + 1 + sep] for row in grid]

    out = []
    for r in range(h):
        row = []
        for c, value in enumerate(pattern[r]):
            if value == 0 or (r < len(mask) and c < len(mask[r]) and mask[r][c] == 0):
                row.append(0)
            else:
                row.append(2)
        out.append(row)
    return out
